column4:
    let instance_before_acquisition = previous_row.instance;
    let outcome = establish_instance(
        &parameters_of_the_pool,
        devices,
        allocator,
        InstanceStart {
            chosen_root,
            effective_root,
            journal,
            previous,
            previous_row,
            first_txg,
            next_counter,
            tree_identifier_watermark_of_the_ring,
            effective_floor,
            abandoned_roots_unreadable,
            shadow_ledger,
            system_configuration,
            space_admission,
            selected_version_journal_position,
            rereads: RereadsOfThisMount {
                read_stage: read_stage_settled,
                instance_table_of_the_newest_root,
            },
            instance_table_sweep,
        },
    );
    if let Err(MountError::Publish(_)) = &outcome {
        let mut rollback_writer = PoolWriter::new(&parameters_of_the_pool, devices.as_mut_slice());
        let _ = rollback_writer.perform(
            crate::transaction::CommitStep::RotateSystemConfigurationSlots {
                journal_tail: 0,
                journal_instance: instance_before_acquisition,
            },
        );
    }
    outcome
}
